    private final V from;
    private final V to;

    public Edge(V from, V to) {
        this.from = Objects.requireNonNull(from, "from vertex must not be null");
        this.to = Objects.requireNonNull(to, "to vertex must not be null");
    }

    public V from() {
        return from;
    }

    public V to() {
        return to;
    }

    @Override
