import java.util.*;
public class SccTest {
    static StronglyConnectedComponentsFinder<Integer> f = new KosarajuStronglyConnectedComponentsFinder<>();
    static Set<Set<Integer>> sccSet(DirectedGraph<Integer> g){
        Set<Set<Integer>> s = new HashSet<>();
        for (var c : f.find(g).components()) s.add(new HashSet<>(c.vertices()));
        return s;
    }
    public static void main(String[] a){
        // 1) single 3-cycle => one SCC {1,2,3}
        var g1 = new DirectedGraphBuilder<Integer>().addEdge(1,2).addEdge(2,3).addEdge(3,1).build();
        assert sccSet(g1).equals(Set.of(Set.of(1,2,3))) : "g1 "+sccSet(g1);

        // 2) two disjoint cycles {1,2},{3,4} + bridge 2->3 (still 2 SCCs)
        var g2 = new DirectedGraphBuilder<Integer>().addEdge(1,2).addEdge(2,1).addEdge(3,4).addEdge(4,3).addEdge(2,3).build();
        assert sccSet(g2).equals(Set.of(Set.of(1,2),Set.of(3,4))) : "g2 "+sccSet(g2);

        // 3) DAG (no cycles) => each vertex its own SCC
        var g3 = new DirectedGraphBuilder<Integer>().addEdge(1,2).addEdge(2,3).addEdge(1,3).build();
        assert sccSet(g3).equals(Set.of(Set.of(1),Set.of(2),Set.of(3))) : "g3 "+sccSet(g3);

        // 4) deep chain of 200000 nodes (would overflow recursion) -> 200000 singletons
        var b = new DirectedGraphBuilder<Integer>();
        int n = 200000;
        for (int i=0;i<n-1;i++) b.addEdge(i,i+1);
        var r4 = f.find(b.build());
        assert r4.count()==n : "g4 count "+r4.count();

        // 5) original example
        var g5 = new DirectedGraphBuilder<Integer>().addEdge(1,3).addEdge(1,4).addEdge(2,1).addEdge(3,2).addEdge(4,5).build();
        assert sccSet(g5).equals(Set.of(Set.of(1,2,3),Set.of(4),Set.of(5))) : "g5 "+sccSet(g5);

        System.out.println("All assertions passed");
    }
}
